def compute(vars):
    revenue = vars["Revenue"]
    cost_of_sales = vars["Cost of Sales"]
    percentage_multiplier = vars["100"]

    if revenue == 0:
        return None

    gross_margin = ((revenue - cost_of_sales) / revenue) * percentage_multiplier

    return {
        "value": gross_margin,
        "trace": {
            "Revenue": revenue,
            "Cost of Sales": cost_of_sales,
            "100": percentage_multiplier,
            "Gross Margin": gross_margin,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
